def check_rectangle_corner_is_reachable(X, Y, circles):
    n = len(circles)

    # Does circle (cx, cy, r) touch the axis-aligned segment (x0,y0)-(x1,y1)?
    def hit(cx, cy, r, x0, y0, x1, y1):
        dx = max(x0 - cx, 0, cx - x1)
        dy = max(y0 - cy, 0, cy - y1)
        return dx * dx + dy * dy <= r * r

    def touches_left_or_top(c):
        x, y, r = c
        return hit(x, y, r, 0, 0, 0, Y) or hit(x, y, r, 0, Y, X, Y)

    def touches_bottom_or_right(c):
        x, y, r = c
        return hit(x, y, r, 0, 0, X, 0) or hit(x, y, r, X, 0, X, Y)

    # A circle covering (or touching) a corner blocks the path outright
    for x, y, r in circles:
        if x * x + y * y <= r * r or (x - X) ** 2 + (y - Y) ** 2 <= r * r:
            return False

    vis = [False] * n
    for s in range(n):
        if vis[s] or not touches_left_or_top(circles[s]):
            continue
        vis[s] = True
        stack = [s]
        while stack:
            i = stack.pop()
            x1, y1, r1 = circles[i]
            # Chain from left/top edge reaches bottom/right edge: corner cut off
            if touches_bottom_or_right(circles[i]):
                return False
            for j in range(n):
                if vis[j]:
                    continue
                x2, y2, r2 = circles[j]
                if (x1 - x2) ** 2 + (y1 - y2) ** 2 > (r1 + r2) ** 2:
                    continue
                # circles intersect; the link only counts if the point on the
                # line between the centers (inside both) is inside the rectangle
                if x1 * r2 + x2 * r1 < (r1 + r2) * X and y1 * r2 + y2 * r1 < (r1 + r2) * Y:
                    vis[j] = True
                    stack.append(j)
    return True
